-- Console schema for postgresql, generated by `scripts/dump_schema_sql.py` from `alembic upgrade head --sql`.
-- Do not edit: change `alembic/versions/` and re-run the script.
--
-- This file creates the tables *and* stamps `alembic_version`, so a database
-- initialised from it is already at head and `alembic upgrade head` is a no-op.
-- It is idempotent only in the sense that re-running it fails on the existing
-- tables — provision an empty database with it.
-- Needs PostgreSQL 12+ (SERIAL keys, JSON columns, TIMESTAMPTZ).

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL,
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_initial

CREATE TABLE param_user (
    id SERIAL NOT NULL,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(16) DEFAULT 'operator' NOT NULL,
    disabled BOOLEAN DEFAULT false NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    last_login_at TIMESTAMP WITH TIME ZONE,
    PRIMARY KEY (id),
    UNIQUE (username)
);

CREATE TABLE param_draft (
    id SERIAL NOT NULL,
    profile VARCHAR(64) NOT NULL,
    base_version INTEGER DEFAULT '0' NOT NULL,
    patch JSON NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (profile)
);

CREATE TABLE param_version (
    id SERIAL NOT NULL,
    profile VARCHAR(64) NOT NULL,
    version INTEGER NOT NULL,
    status VARCHAR(16) NOT NULL,
    note VARCHAR(500) DEFAULT '' NOT NULL,
    author VARCHAR(64) DEFAULT '' NOT NULL,
    yaml_text TEXT DEFAULT '' NOT NULL,
    yaml_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    env_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    duration_s FLOAT,
    rolled_back_to INTEGER,
    error_code VARCHAR(48),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_version_profile_version UNIQUE (profile, version)
);

CREATE TABLE param_audit (
    id SERIAL NOT NULL,
    at TIMESTAMP WITH TIME ZONE NOT NULL,
    actor VARCHAR(64) DEFAULT '' NOT NULL,
    role VARCHAR(16) DEFAULT '' NOT NULL,
    action VARCHAR(32) NOT NULL,
    profile VARCHAR(64) DEFAULT '' NOT NULL,
    version INTEGER,
    fields JSON NOT NULL,
    result VARCHAR(8) DEFAULT 'ok' NOT NULL,
    error_code VARCHAR(48),
    duration_s FLOAT,
    request_id VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id)
);

INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING alembic_version.version_num;

-- Running upgrade 0001_initial -> 0003_voices

CREATE TABLE voices (
    id VARCHAR(26) NOT NULL,
    name VARCHAR(64) NOT NULL,
    source VARCHAR(16) NOT NULL,
    backend VARCHAR(16) NOT NULL,
    language VARCHAR(16),
    status VARCHAR(16) DEFAULT 'draft' NOT NULL,
    audio_relpath VARCHAR(255),
    audio_bytes INTEGER DEFAULT '0' NOT NULL,
    audio_seconds FLOAT DEFAULT '0' NOT NULL,
    trim_start_ms INTEGER DEFAULT '0' NOT NULL,
    trim_end_ms INTEGER,
    ref_text TEXT,
    instruct TEXT,
    spk_relpath VARCHAR(255),
    rvq_relpath VARCHAR(255),
    error_code VARCHAR(32),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by VARCHAR(64) NOT NULL,
    consent_ack_at TIMESTAMP WITH TIME ZONE NOT NULL,
    retention_days INTEGER DEFAULT '30' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_voices_name UNIQUE (name)
);

CREATE INDEX ix_voices_status ON voices (status);

UPDATE alembic_version SET version_num='0003_voices' WHERE alembic_version.version_num = '0001_initial';

-- Running upgrade 0003_voices -> 0004_turn_latency

CREATE TABLE turn_latency (
    response_key VARCHAR(96) NOT NULL,
    turn_revision INTEGER NOT NULL,
    turn_id VARCHAR(96),
    source VARCHAR(16) DEFAULT '' NOT NULL,
    status VARCHAR(16) DEFAULT '' NOT NULL,
    smart_status VARCHAR(16),
    e2e_ms INTEGER,
    stt_ms INTEGER,
    llm_ms INTEGER,
    tts_ttfa_ms INTEGER,
    vad_decision_ms INTEGER,
    hold_ms INTEGER,
    logged_at TIMESTAMP WITH TIME ZONE NOT NULL,
    raw_offset INTEGER DEFAULT '0' NOT NULL,
    ingested_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (response_key, turn_revision)
);

CREATE INDEX ix_turn_latency_logged_at ON turn_latency (logged_at);

UPDATE alembic_version SET version_num='0004_turn_latency' WHERE alembic_version.version_num = '0003_voices';

-- Running upgrade 0004_turn_latency -> 0005_instances

CREATE TABLE param_instance (
    id SERIAL NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    base_url VARCHAR(255) NOT NULL,
    weight INTEGER DEFAULT '1' NOT NULL,
    max_sessions_hint INTEGER,
    labels_json JSON NOT NULL,
    enabled BOOLEAN DEFAULT '1' NOT NULL,
    drain_requested BOOLEAN DEFAULT '0' NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_instance_instance_id UNIQUE (instance_id)
);

CREATE TABLE param_instance_metric (
    id SERIAL NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    observed_at TIMESTAMP WITH TIME ZONE NOT NULL,
    observed_by VARCHAR(64) NOT NULL,
    kind VARCHAR(16) DEFAULT 'sample' NOT NULL,
    size INTEGER,
    in_use INTEGER,
    free INTEGER,
    stuck INTEGER,
    status VARCHAR(16) NOT NULL,
    probe_ms INTEGER,
    alloc_ok INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_no_instance INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_instance_503 INTEGER DEFAULT '0' NOT NULL,
    evict_count INTEGER DEFAULT '0' NOT NULL,
    recover_count INTEGER DEFAULT '0' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_instance_metric_instance_id ON param_instance_metric (instance_id);

CREATE INDEX ix_param_instance_metric_observed_at ON param_instance_metric (observed_at);

UPDATE alembic_version SET version_num='0005_instances' WHERE alembic_version.version_num = '0004_turn_latency';

-- Running upgrade 0005_instances -> 0006_clusters

CREATE TABLE param_cluster (
    id SERIAL NOT NULL,
    name VARCHAR(64) NOT NULL,
    registry VARCHAR(255) DEFAULT '' NOT NULL,
    policy VARCHAR(16) DEFAULT 'least' NOT NULL,
    note VARCHAR(255) DEFAULT '' NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_cluster_name UNIQUE (name)
);

INSERT INTO param_cluster (name, registry, policy, note, created_at, updated_at, updated_by) SELECT 'default', '', 'least', '', now(), now(), 'migration' WHERE NOT EXISTS (SELECT 1 FROM param_cluster WHERE name = 'default');

ALTER TABLE param_instance ADD COLUMN cluster_id VARCHAR(64) DEFAULT 'default' NOT NULL;

CREATE INDEX ix_param_instance_cluster_id ON param_instance (cluster_id);

UPDATE alembic_version SET version_num='0006_clusters' WHERE alembic_version.version_num = '0005_instances';

-- Running upgrade 0006_clusters -> 0007_comments

COMMENT ON TABLE "param_user" IS '控制台操作员账号与角色，用于登录鉴权';

COMMENT ON TABLE "param_audit" IS '操作审计日志，仅追加；fields 只存字段名不存值';

COMMENT ON TABLE "param_cluster" IS '集群登记表：一个负载均衡注册中心界定一个集群';

COMMENT ON TABLE "param_draft" IS '配置草稿：每个配置档一份增量补丁，不是整份配置';

COMMENT ON TABLE "param_instance" IS 'Pipeline 实例注册表，运维开关与集群归属落库';

COMMENT ON TABLE "param_instance_metric" IS '实例状态与分配计数采样；计数为窗口增量而非累计值，空值表示不可得';

COMMENT ON TABLE "param_instance_runtime" IS '实例运行时状态：健康五态、槽位占用、能力指纹与占位数，跨控制台副本共享';

COMMENT ON TABLE "param_allocator_lease" IS '选台占位租约明细：预留待连接的租约与已建立会话的占用都占槽位';

COMMENT ON TABLE "param_proxy_metric" IS '数据面代理采样：按实例与服务记录成功数与失败原因，成功数为窗口增量';

COMMENT ON TABLE "param_config" IS '控制台配置项登记表：库中的值优先于环境变量，改完数秒内生效';

COMMENT ON TABLE "param_machine" IS '机器实体：agent 注册与心跳的落点，实例挂载与机器状态的单一来源';

COMMENT ON TABLE "param_machine_workload" IS '机器负载声明：心跳清单全量覆盖，按机器与负载类型对齐';

COMMENT ON TABLE "param_machine_config" IS '机器实际生效配置，与配置档期望值比对得出漂移数';

COMMENT ON TABLE "param_machine_draft" IS '机器级待下发草稿：配置档渲染后按本表覆盖对应键';

COMMENT ON TABLE "param_agent_config_version" IS 'agent 目标配置下发快照，按机器保留最近若干版';

COMMENT ON TABLE "param_token_metric" IS '机器与负载的 token 增量时序，计数为窗口增量而非累计值';

COMMENT ON TABLE "param_lb_rule" IS '负载均衡路由规则，按优先级升序首条命中生效';

COMMENT ON TABLE "param_lb_affinity" IS '会话亲和记录：命中粘性键则跳过规则评估直接选台';

COMMENT ON TABLE "param_lb_route_log" IS '路由决策记账，只追加，用于命中率与规则命中统计';

COMMENT ON TABLE "param_release" IS '发布流水线台账：外部 CI 执行构建与验证，控制台只记录过程';

COMMENT ON TABLE "param_version" IS '配置版本快照，创建后不可变；保存配置全文用于启动自检';

COMMENT ON TABLE "turn_latency" IS '单轮语音延迟索引，可由日志重建，只存原始毫秒值';

COMMENT ON TABLE "voices" IS '音色上传记录，音频与特征路径相对音色数据卷保存';

COMMENT ON COLUMN "param_user"."id" IS '主键标识';

COMMENT ON COLUMN "param_user"."username" IS '登录用户名，全局唯一';

COMMENT ON COLUMN "param_user"."password_hash" IS '口令哈希，不存明文';

COMMENT ON COLUMN "param_user"."role" IS '角色：admin 或 operator';

