COMMENT ON COLUMN "param_instance_metric"."status" IS '实例状态';

COMMENT ON COLUMN "param_instance_metric"."probe_ms" IS '探活耗时（毫秒）';

COMMENT ON COLUMN "param_instance_metric"."alloc_ok" IS '本采样窗口内分配成功次数';

